{
  "witnessCode": "import { strict as assert } from 'node:assert';
import { test } from 'node:test';
import normalizeUrl from '../index.js';

test('normalizeUrl keeps query parameters when keepQueryParameters is empty array', () => {
  const url = 'http://example.com?a=1&b=2';
  const options = { keepQueryParameters: [] };
  const result = normalizeUrl(url, options);
  // In base, query parameters should be preserved, resulting in trailing slash before ?
  assert.strictEqual(result, 'http://example.com/?a=1&b=2');
});"
}
